def solve() -> int:
    chicken_price = 10
    chicken_weight = 40
    if chicken_weight > 50:
      discount = chicken_weight * 0.1
    else:
      discount = chicken_weight * 0.2
    total_price = (chicken_price * chicken_weight) - discount
    result = total_price
    return result

